import java.util.concurrent.*;import java.util.*;
public class MiniBank {
    static class TransactionProcessor {private final ExecutorService pool=Executors.newFixedThreadPool(4);void submit(Runnable r){pool.execute(r);}void stop()throws InterruptedException{pool.shutdown();if(!pool.awaitTermination(10,TimeUnit.SECONDS))pool.shutdownNow();}}
    static class Account {final String number;long balance;Account(String n,long b){number=n;balance=b;}synchronized void deposit(long a){balance+=a;}}
    static class TransactionBuffer {private final String[] data=new String[4];private int count=0; synchronized void put(String s)throws InterruptedException{while(count==data.length)wait();data[count++]=s;notifyAll();} synchronized String take()throws InterruptedException{while(count==0)wait();String s=data[0];System.arraycopy(data,1,data,0,--count);notifyAll();return s;}}
    static void transfer(Account from,Account to,long amount){Account first=from.number.compareTo(to.number)<0?from:to;Account second=first==from?to:from;synchronized(first){synchronized(second){if(from.balance>=amount){from.balance-=amount;to.balance+=amount;}}}}
    public static void main(String[] args)throws Exception{Account a=new Account("AC0001",0);TransactionProcessor p=new TransactionProcessor();for(int i=0;i<100;i++)p.submit(()->a.deposit(1));p.stop();System.out.println("Pool balance: "+a.balance);TransactionBuffer b=new TransactionBuffer();Thread producer=new Thread(()->{try{for(int i=1;i<=5;i++)b.put("TX"+i);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread consumer=new Thread(()->{try{for(int i=1;i<=5;i++)System.out.println("Processed "+b.take());}catch(InterruptedException e){Thread.currentThread().interrupt();}});producer.start();consumer.start();producer.join();consumer.join();Account x=new Account("AC0002",1000),y=new Account("AC0001",500);transfer(x,y,100);transfer(y,x,50);System.out.println("Transfer balances: "+x.balance+", "+y.balance);}
}
